INSERT INTO `reviews` (`review_id`, `product_id`, `user_id`, `rating`, `comment`, `status`, `created_at`, `updated_at`, `is_deleted`, `order_id`, `sentiment`) VALUES
(1, 1, 12, 5, 'Sản phẩm rất xịn, đế giày êm ái, đi chạy 10km không thấy mỏi chân. Hàng thật chất lượng tốt lắm!', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(2, 1, 8, 4, 'Giày đẹp, đủ size, giao hàng nhanh. Chỉ trừ là hộp quá chút.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(3, 1, 9, 5, 'Đã mua lần 2 vì quá xài lần đầu thích lắm. Điều kiện giao hàng tốt.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(4, 3, 10, 5, 'Giày Nike nhẹ, đẹp, ôm chân rất vừa. Xứng đáng với giá tiền.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(5, 3, 11, 4, 'Chất lượng tốt, thiết kế hiện đại. Gì giao hàng hơi lâu một chút.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(6, 3, 12, 5, 'Đã từng dùng nhiều dòng giày khác nhau, Revolution 7 là dòng kinh tế nhất mà chất lượng thực sự ok.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(7, 5, 8, 5, 'Mua cho chồng tập marathon, anh ấy rất thích, nói là đếm tốt hơn tất cả giày cũ. Giao hàng nhanh.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(8, 5, 13, 5, 'Giày chạy bộ đỉnh nhất tôi từng dùng. Gel phần sau giảm sốc rất tốt. Rất đáng tiền.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(9, 25, 12, 5, 'Vợt cầu lông đỉnh của đỉnh, cần đà tốt, góp chơi của tôi rất nhiều. Hàng chính hãng 100%.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(10, 25, 9, 5, 'Mua tặng anh trai sinh nhật, anh ấy mê lắm. Đóng gói đẹp, có chứng nhận hàng chính hãng.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(11, 25, 11, 4, 'Vợt rất tốt nhưng giá hơi cao. Nếu dùng cho chuyên nghiệp thì xứng đáng đầu tư.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(12, 26, 8, 5, 'Vợt phản công siêu nhanh, day chac, cam tay vua. Rat hai long.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(13, 26, 10, 4, 'Vợt tốt, nhẹ, phù hợp người chơi phản công. Ship nhanh.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(14, 28, 13, 4, 'Vợt giá tốt mà chơi được, phù hợp người mới bắt đầu như mình. Nên mua.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(15, 28, 11, 3, 'Vợt ok cho giá tiền, nhưng khung hơi bị rung, có lẽ do mình chơi mạnh.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(16, 31, 12, 5, 'Cầu bay đẹp, độ bền khá ổn, mua nhiều lần rồi. Giá tốt.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(17, 31, 9, 4, 'Dùng được khoảng 30-40 hiệu, không tệ. Nảy rất ổn cho cầu giao lưu.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(18, 16, 8, 5, 'Vải đẹp, thoáng mát, màu không bị bám sau nhiều lần giặt. Rất hài lòng.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(19, 16, 13, 4, 'Áo vừa vặn, chất lượng ok với mức giá. Khuyên bạn nên mua.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(20, 38, 8, 5, 'Quần chất, ôm sát nhưng không bị bó. Dùng cho yoga hàng ngày. Ship nhanh!', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(21, 38, 10, 5, 'Chất lượng rất tốt, giá hợp lý. Mua lần thứ 3 rồi vẫn rất thích.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(22, 23, 8, 4, 'Áo ôm đẹp, hỗ trợ tốt, chất liệu thoáng. Giao hàng nhanh.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(23, 23, 13, 5, 'Mua tập yoga, chất lượng rất tốt, không bại sau nhiều buổi tập. Hài lòng.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(24, 44, 9, 4, 'Tạ chắc, bọc cao su không bị tuột, đem được lâu. Giá rẻ.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(25, 44, 11, 4, 'Mua loại 3kg, chất lượng ok. Cảm ơn shop.', 'approved', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(26, 1, 13, 2, 'Hàng bị lỗi, mũi giày bị tách. Cần kiểm tra lại chất lượng trước khi gửi hàng!', 'pending', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(27, 25, 13, 1, 'Vợt bị bong dây khi mới mua, phải đợi 1 tuần mới xong. Rất phiền.', 'pending', '2026-05-29 19:17:55', '2026-06-11 01:04:10', 0, NULL, 'neutral'),
(32, 189, 12, 4, 'Sản phẩm rất đẹp, đúng như hình.', 'approved', '2026-06-17 08:41:16', '2026-06-17 08:41:16', 0, 50119, 'neutral'),
(33, 189, 28, 4, 'Màu sắc bên ngoài đẹp hơn trong ảnh.', 'approved', '2026-06-17 08:41:16', '2026-06-17 08:41:16', 0, 50120, 'neutral'),
(34, 189, 29, 5, 'Tuyệt vời, 5 sao cho chất lượng dịch vụ.', 'approved', '2026-06-17 08:41:16', '2026-06-17 08:41:16', 0, 50121, 'neutral'),
